import React, { useEffect, useState } from "react";

function Dashboard() {
  const [responseData, setResponseData] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const baseUrl = "https://novaoffice.novasoftwares.com/service.aspx";
    const loginPayload = {
      userid: "jay",
      password: "jay123",
    };

    const queryParams = new URLSearchParams({
      ApiVer: "1",
      Devid: "online",
      AppId: "NV01",
      Lat: "0",
      Lng: "0",
      Control: "auth",
      data: JSON.stringify(loginPayload),
    });

    fetch(`${baseUrl}?${queryParams.toString()}`) // ✅ Corrected template literal
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch");
        return res.json();
      })
      .then((data) => {
        if (
          Array.isArray(data) &&
          data.length > 0 &&
          data[0].Result === "error"
        ) {
          setError("Invalid user ID or password.");
        } else {
          setResponseData(data);
        }
        setLoading(false);
      })
      .catch((err) => {
        console.error("Fetch error:", err);
        setError("Something went wrong while connecting to the server.");
        setLoading(false);
      });
  }, []);

  return (
    <div
      style={{
        padding: "2rem",
        fontFamily: "Arial",
        backgroundImage:
          "url('https://img.freepik.com/free-photo/business-partners-handshake-global-corporate-with-technology-concept_53876-102615.jpg')",
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        minHeight: "100vh",
      }}
    >
      <div
        style={{ textAlign: "center", color: "black", marginBottom: "2rem" }}
      >
        <h2>Fetched Unit Details</h2>
      </div>

      {loading ? (
        <p>Loading...</p>
      ) : error ? (
        <div
          style={{
            backgroundColor: "#ffe6e6",
            color: "#cc0000",
            padding: "1rem",
            border: "1px solid #cc0000",
            borderRadius: "8px",
            maxWidth: "600px",
            margin: "0 auto",
            background: "white",
          }}
        >
          <strong>Error:</strong> {error}
        </div>
      ) : (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "1rem",
            justifyContent: "center",
          }}
        >
          {responseData.map((item, index) => (
            <div
              key={index}
              style={{
                flex: "0 1 300px",
                padding: "1rem",
                border: "1px solid #ddd",
                borderRadius: "8px",
                backgroundColor: "white",
              }}
            >
              <p>
                <strong>Unit ID:</strong> {item.UnitId}
              </p>
              <p>
                <strong>Unit Name:</strong> {item.UnitName}
              </p>
              <p>
                <strong>User ID:</strong> {item.UserId}
              </p>
              <p>
                <strong>Image:</strong> <br />
                <img
                  src={item.Url}
                  alt="Unit"
                  style={{
                    width: "100px",
                    height: "100px",
                    objectFit: "contain",
                    marginLeft: "70px",
                  }}
                />
              </p>
              <div>
                <strong>Address:</strong>
                <div style={{ marginLeft: "1rem", marginTop: "0.5rem" }}>
                  {(() => {
                    try {
                      const parsedAddress = JSON.parse(item.Address);
                      return parsedAddress.map((entry, idx) => {
                        const [_, value] = Object.entries(entry)[0];
                        return <div key={idx}>{value}</div>;
                      });
                    } catch {
                      return <div>Invalid address</div>;
                    }
                  })()}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Dashboard;
